'use client'

import { useState } from 'react'
import { Menu, X } from 'lucide-react'

import { Sheet, SheetContent, SheetTitle, SheetTrigger } from '../../components/ui/sheet'
import { ProductMark } from '../../components/ui/product-mark'
import type { ProductMarkProps } from '../../components/ui/product-mark'

/** One destination in the mobile panel, which is the site's own navigation. */
export type MobileNavLink = {
  /** The text of the link. */
  label: string
  /** Where the link goes. */
  href: string
  /** Marks this link as the page the reader is on. */
  current?: boolean
}

/** The props the mobile navigation takes. */
export type MobileNavProps = {
  /** The product this navigation belongs to, drawn as the mark above the list. */
  product: Pick<ProductMarkProps, 'id' | 'name' | 'pack'>
  /** Every destination, in the order a reader should meet them. */
  links: readonly MobileNavLink[]
  /** The accessible name of the panel, which is also the trigger's name. */
  label: string
  /** The word on the trigger while the panel is closed. */
  openLabel: string
  /** The word on the trigger while the panel is open. */
  closeLabel: string
}

/**
 * The navigation for viewports below the row's own threshold.
 *
 * **It carries every destination, not a subset.** From the narrowest phone up to
 * the width the horizontal row is authored for, this panel is the only way to reach
 * a section of the site, so a link the row shows at `lg` and the panel omits at
 * 640 is a route a reader on a small laptop cannot find at all. Both render the one
 * array, so a destination added to one is in the other by construction rather than
 * by remembering twice.
 *
 * **It is a Sheet rather than a disclosure panel of the navbar's own, and the
 * difference is the overlay.** A panel that is a child of the bar sits over the
 * page with the bar still visible and nothing above the rest of the document, so
 * scrolling the page behind it moves content the reader thought was dismissed. A
 * sheet owns a modal surface: the rest of the page is not reachable, Escape closes
 * it, and focus is held inside it and handed back to the trigger on the way out.
 * That is the behaviour a full-width menu over a long page needs, and it is the
 * behaviour Prism's own navigation had to hand-write.
 *
 * The links are full width with a 44 pixel minimum height, because below the row's
 * threshold this is a touch target and not a line of text, and the coarse-pointer
 * floor in the design system asks for exactly that.
 */
export function MobileNav({
  product,
  links,
  label,
  openLabel,
  closeLabel,
}: MobileNavProps) {
  const [open, setOpen] = useState(false)

  return (
    <Sheet open={open} onOpenChange={setOpen}>
      <SheetTrigger
        data-slot="site-navbar-mobile-trigger"
        aria-label={open ? closeLabel : openLabel}
        className="border-border bg-card text-foreground hover:bg-accent hover:text-accent-foreground focus-visible:border-ring focus-visible:ring-ring flex size-11 shrink-0 items-center justify-center rounded-full border transition-colors focus-visible:ring-[3px] focus-visible:outline-none lg:hidden"
      >
        {open ? <X aria-hidden className="size-5" /> : <Menu aria-hidden className="size-5" />}
      </SheetTrigger>

      <SheetContent side="right" className="w-80">
        <SheetTitle className="sr-only">{label}</SheetTitle>
        <nav aria-label={label} className="flex flex-col gap-1">
          <div className="mb-4 flex items-center">
            <ProductMark id={product.id} name={product.name} pack={product.pack} size="md" />
          </div>
          {links.map((link) => (
            <a
              key={link.href}
              href={link.href}
              aria-current={link.current ? 'page' : undefined}
              onClick={() => setOpen(false)}
              className={
                link.current
                  ? 'bg-accent text-accent-foreground focus-visible:border-ring focus-visible:ring-ring flex min-h-11 items-center rounded-lg px-3 text-sm font-medium transition-colors focus-visible:ring-[3px] focus-visible:outline-none'
                  : 'text-muted-foreground hover:bg-accent hover:text-accent-foreground focus-visible:border-ring focus-visible:ring-ring flex min-h-11 items-center rounded-lg px-3 text-sm font-medium transition-colors focus-visible:ring-[3px] focus-visible:outline-none'
              }
            >
              {link.label}
            </a>
          ))}
        </nav>
      </SheetContent>
    </Sheet>
  )
}

'use client'

import type { Mode, PackId } from '../../theming'
import type { SearchDialogMessages } from '../../components/ui/search-dialog'
import { ModeToggle } from './mode-toggle'
import { SearchEntry } from './search-entry'
import { SitesMenu } from './sites-menu'
import { ThemeMenu, type ThemePack } from './theme-menu'
import type { SwitcherProduct } from '../../components/ui/product-switcher'
import type { MobileNavLink } from './mobile-nav'
import { MobileNav } from './mobile-nav'
import { PrismProvider } from '../../provider/provider'

/** What the control cluster was told to render. Every field is optional. */
export type NavbarControlsProps = {
  /** The product whose mark heads the mobile panel. */
  product: { id: string; name: string; pack?: PackId | null }
  /** The site's own destinations, for the panel below the row's threshold. */
  nav: readonly MobileNavLink[]
  /** The accessible name of the panel and of its trigger. */
  navLabel: string
  /** The set of sites, or nothing for a site that is the only one. */
  sites?: readonly SwitcherProduct[]
  /** The `id` of the site the reader is on. */
  currentSiteId?: string
  /** The accessible name of the sites menu. */
  sitesLabel?: string
  /** Where the search index is served from, or nothing for no search. */
  search?: {
    indexUrl: string
    label: string
    hint?: string
    messages: SearchDialogMessages
  }
  /** The packs the chooser offers, or nothing for no chooser. */
  theme?: { label: string; packs?: readonly ThemePack[] }
  /** The two names of the light and dark control, or nothing for no toggle. */
  mode?: { lightLabel: string; darkLabel: string }
  /** The two names of the mobile trigger. */
  mobileLabels: { open: string; close: string }
  /** The pack a reader with no stored choice gets. */
  defaultPack: PackId
  /** The mode a reader with no stored choice gets. */
  defaultMode: Mode
  /** A slot for controls the consumer owns, after the ones above. */
  actions?: React.ReactNode
}

/**
 * The bar's controls, and the only client boundary in the navbar.
 *
 * Everything interactive in a site header is application state: what a reader has
 * chosen, what is open, what a search found. None of it is a fact the bar can be
 * told, so none of it can live in a server Component, and the boundary is drawn
 * here rather than around the whole bar so that the brand lockup and the
 * navigation stay server rendered. That is the arrangement that lets a site keep
 * the rest of its page free of client JavaScript, which is the property three of
 * the five NaniSoft sites are built around.
 *
 * **The provider is mounted here and not in the site's root layout, and that is
 * deliberate.** A provider in the layout would wrap every page and every provider
 * is context, so a page that never renders a control would still ship it. Mounted
 * around five buttons, it ships with the buttons and stops there. It is also the
 * only writer of the two attributes the boot script reads, so a choice made here
 * is a choice the next page load resolves to the same theme.
 *
 * **The order is fixed and it is a reading order, not a preference.** Search first
 * because it is the only control that answers a question the reader arrived with;
 * then the two menus, which are choices about where to be rather than about what to
 * do; then the mode, which is the choice that persists across every site in the
 * family; then the mobile trigger, which is last because it is the only one that
 * appears at the narrow end of the range and appears alone there.
 */
export function NavbarControls(props: NavbarControlsProps) {
  const {
    product,
    nav,
    navLabel,
    sites,
    currentSiteId,
    sitesLabel,
    search,
    theme,
    mode,
    mobileLabels,
    defaultPack,
    defaultMode,
    actions,
  } = props

  const hasThemeControls = Boolean(theme) || Boolean(mode)
  if (!search && !sites && !hasThemeControls && !actions && nav.length === 0) return null

  return (
    <PrismProvider defaultPack={defaultPack} defaultMode={defaultMode}>
      <div className="ms-auto flex items-center gap-2">
        {search ? (
          <SearchEntry
            indexUrl={search.indexUrl}
            label={search.label}
            hint={search.hint}
            messages={search.messages}
          />
        ) : null}

        {sites && sites.length > 0 && sitesLabel ? (
          <SitesMenu sites={sites} currentId={currentSiteId} label={sitesLabel} />
        ) : null}

        {theme ? <ThemeMenu label={theme.label} packs={theme.packs} /> : null}

        {mode ? <ModeToggle lightLabel={mode.lightLabel} darkLabel={mode.darkLabel} /> : null}

        {actions}

        {nav.length > 0 ? (
          <MobileNav
            product={product}
            links={nav}
            label={navLabel}
            openLabel={mobileLabels.open}
            closeLabel={mobileLabels.close}
          />
        ) : null}
      </div>
    </PrismProvider>
  )
}
